// Silent worker-pool keep-alive. Mounted whenever the user is on a
// route that might lead to PR-detail (inbox or pr) so the singleton
// stays alive across `inbox ↔ pr` navigation — otherwise the lib's
// instanceCount drops to 0 on PRDetailScreen unmount and the pool
// gets torn down, forcing every subsequent PR open to re-pay the
// worker-spawn + Shiki-init cost.
//
// Also primes the pool eagerly the moment the user reaches Inbox so
// the FIRST PR open isn't a flash of unhighlighted code:
//   - Importing this module pulls in @pierre/diffs (the lazy chunk)
//   - Mounting the Provider calls getOrCreateWorkerPoolSingleton,
//     which spawns 8 workers and starts Shiki theme/grammar loading
//   - By the time the user clicks a PR card, tokenization is ready
//
// This is the WorkerPoolContextProvider exactly — no extra logic.
// PRDetailScreen still mounts its own Provider; the two share the
// same singleton (instanceCount becomes 2). When PRDetail unmounts,
// instanceCount drops to 1 — pool stays alive. When the user fully
// leaves the inbox/pr area (back to Setup, signed out), this
// Provider unmounts too and the pool terminates.

import { useMemo } from 'react';
import { WorkerPoolContextProvider } from '@pierre/diffs/react';
import { diffsWorkerFactory } from './diffsWorker';
import { loadPrefs } from './diffPreferences';

export function WorkerPoolPrewarm() {
  const prefs = useMemo(() => loadPrefs(), []);
  return (
    <WorkerPoolContextProvider
      poolOptions={{ workerFactory: diffsWorkerFactory }}
      highlighterOptions={{
        theme: prefs.theme,
        lineDiffType: prefs.lineDiffStyle,
      }}
    >
      {/* Empty — this Provider exists only to keep the singleton
          alive. The actual diff UI is rendered inside its own
          nested Provider in PRDetailScreen. */}
      {null}
    </WorkerPoolContextProvider>
  );
}
